<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\TrustedClientEnabledVO;

trait TrustedClientEnabledAttributeHolder
{
    protected TrustedClientEnabledVO|bool|null $enabled = null;
    protected bool $enabledAssigned = false;

    public function getEnabledOrCurrent(TrustedClientEnabledVO $enabled): TrustedClientEnabledVO
    {
        if ($this->enabledAssigned) {
            \assert(null !== $this->enabled);
            return TrustedClientEnabledVO::from($this->enabled);
        } else {
            return $enabled;
        }
    }
    public function enabledTryBuildInitial(ConstraintFailList $error): ?TrustedClientEnabledVO
    {
        return  TrustedClientEnabledVO::tryFrom($this->enabledAssigned ? $this->enabled : false, $error);
    }
    public function enabled(TrustedClientEnabledVO|bool $enabled): static
    {
        $this->enabled = $enabled;
        $this->enabledAssigned = true;
        return $this;
    }
    public function isEnabled(): ?bool
    {
        return $this->enabled instanceof TrustedClientEnabledVO ? $this->enabled->value() : $this->enabled;
    }
    public function isEnabledAssigned(): bool
    {
        return $this->enabledAssigned;
    }
    public function writeEnabledTo(mixed $att): void
    {
        if ($this->enabledAssigned) {
            \assert(null !== $this->enabled);
            $att->enabled($this->enabled);
        }
    }
    public function readEnabledFrom(mixed $att): void
    {
        if ($att->isEnabledAssigned()) {
            $enabled = $att->isEnabled();
            \assert(null !== $enabled);
            $this->enabled($enabled);
        }
    }
    public function unsetEnabled(): static
    {
        $this->enabledAssigned = false;
        return $this;
    }
    protected function withDefaultEnabled(): void
    {
        if ($this->enabled === null) {
            $this->enabled = false;
        }
    }
    protected function withAssertedEnabledRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->enabledAssigned = $this->enabledAssigned) {
            $value->enabled = TrustedClientEnabledVO::tryFrom($this->enabled, $errorsList);
        }
    }
}
